package uz.plugin.ogg_record_player

/**
 * The API Dart calls through JNI (bindings in `lib/src/bindings/ogg_record_player_api.g.dart`, generated by
 * `dart run tool/jnigen.dart` from the compiled class). Only primitive, [String] and [ByteArray] types cross the
 * boundary; every call goes to the engine's [OggRecordPlayerHost].
 *
 * Results and failures come back through callbacks, failures as the shared [PlayerError] codes. Calls made while
 * no engine is attached answer `UNKNOWN` or do nothing.
 */
object OggRecordPlayerApi {

    /** State changes of every player; [errorCode] is set only for state 4 (failed). */
    interface PlayerListener {
        fun onStateChanged(
            playerId: Int,
            state: Int,
            position: Double,
            duration: Double,
            speed: Double,
            errorCode: String?,
        )
    }

    /** Recorder results, the same events and payloads as the former `onRecorder*` channel callbacks. */
    interface RecorderListener {
        fun onCanceled(recorderId: Int, reason: Int)

        fun onStartFailed(recorderId: Int, error: String)

        fun onFinished(recorderId: Int, durationMillis: Long, waveform: ByteArray)
    }

    /** Answers one `createFrom*` call. */
    interface CreateCallback {
        fun onCreated(playerId: Int)

        fun onFailed(code: String, message: String, details: String?)
    }

    /** [known] is false when the duration is unavailable; [seconds] is then meaningless. */
    interface DurationCallback {
        fun onDuration(known: Boolean, seconds: Double)
    }

    interface DoneCallback {
        fun onDone()
    }

    /** Replaces the listeners of the current engine; a hot restart registers new ones. */
    @JvmStatic
    fun setListeners(playerListener: PlayerListener, recorderListener: RecorderListener) {
        OggRecordPlayerHost.current?.setListeners(playerListener, recorderListener)
    }

    @JvmStatic
    fun createFromFile(path: String, callback: CreateCallback) {
        val host = OggRecordPlayerHost.current
        if (host == null) detached(callback) else host.createFromFile(path, callback)
    }

    @JvmStatic
    fun createFromUrl(url: String, callback: CreateCallback) {
        val host = OggRecordPlayerHost.current
        if (host == null) detached(callback) else host.createFromUrl(url, callback)
    }

    @JvmStatic
    fun createFromBytes(bytes: ByteArray, callback: CreateCallback) {
        val host = OggRecordPlayerHost.current
        if (host == null) detached(callback) else host.createFromBytes(bytes, callback)
    }

    @JvmStatic
    fun warmUp(callback: DoneCallback) {
        OggRecordPlayerHost.warmUp(callback)
    }

    @JvmStatic
    fun play(playerId: Int) {
        OggRecordPlayerHost.current?.play(playerId)
    }

    @JvmStatic
    fun pause(playerId: Int) {
        OggRecordPlayerHost.current?.pause(playerId)
    }

    /** Stops and releases the player; its id is invalid afterwards. */
    @JvmStatic
    fun stop(playerId: Int) {
        OggRecordPlayerHost.current?.stop(playerId)
    }

    @JvmStatic
    fun getDuration(playerId: Int, callback: DurationCallback) {
        val host = OggRecordPlayerHost.current
        if (host == null) callback.onDuration(false, 0.0) else host.getDuration(playerId, callback)
    }

    @JvmStatic
    fun setPlaybackSpeed(playerId: Int, speed: Double) {
        OggRecordPlayerHost.current?.setPlaybackSpeed(playerId, speed)
    }

    /** Returns the recorder id, or -1 when [path] is empty or no engine is attached. */
    @JvmStatic
    fun createRecorder(path: String): Int = OggRecordPlayerHost.current?.createRecorder(path) ?: -1

    /** Returns null once the recording was started, else an `OggOpusRecorderException` code. */
    @JvmStatic
    fun startRecord(recorderId: Int): String? {
        val host = OggRecordPlayerHost.current ?: return "UNKNOWN"
        return host.startRecord(recorderId)
    }

    @JvmStatic
    fun stopRecord(recorderId: Int) {
        OggRecordPlayerHost.current?.stopRecord(recorderId)
    }

    @JvmStatic
    fun destroyRecorder(recorderId: Int) {
        OggRecordPlayerHost.current?.destroyRecorder(recorderId)
    }

    private fun detached(callback: CreateCallback) {
        callback.onFailed("UNKNOWN", "Failed to create player", "no Flutter engine is attached")
    }
}
